questionvariables.text:
/* List of Pythagorean triples: [radius, height, slant height] */
list_of_the_values:[
    [3,4,5],[6,8,10],[9,12,15],[5,12,13],[7,24,25],[8,15,17],
    [9,40,41],[11,60,61],[12,35,37],[13,84,85],[16,63,65],
    [20,21,29],[33,56,65],[36,77,85],[39,80,89],[48,55,73],
    [60,91,109],[65,72,97],[80,99,121],[15,20,25],[35,72,85],
    [36,77,85],[39,80,89],[80,84,116]
];

/* Randomly choose one set of dimensions */
index:1+rand(length(list_of_the_values));
choose_one:list_of_the_values[index];

base_radius_of_the_cone:choose_one[1];
height_of_the_cone:choose_one[2];
slantheight_of_the_cone:choose_one[3];

/* Short aliases */
r:base_radius_of_the_cone;
l:slantheight_of_the_cone;
h:height_of_the_cone;

/* Students are told to use pi = 22/7 */
mypi:22/7;

/* Exact exposed areas: curved cone (pi r l) + curved hemisphere (2 pi r^2) */
Area_cone_exact:mypi*r*l;
Hemisphere_exact:2*mypi*r^2;
SA_exact:Area_cone_exact+Hemisphere_exact;

/* Values rounded to 2 d.p. for display and marking */
Area_cone:float(round(100*Area_cone_exact)/100);
Hemisphere_area:float(round(100*Hemisphere_exact)/100);
Surface_Area:float(round(100*SA_exact)/100);

/* Worked-solution helpers */
R_times_l:r*l;
R1:r^2;

/* ----------------------------------------------------------- */
/* Common student mistakes (rounded to 2 d.p. to match marking) */
/* ----------------------------------------------------------- */

/* Mistake 1: used the surface area of a whole sphere (4 pi r^2)
   instead of a hemisphere (2 pi r^2) */
sphere_mistake:float(round(100*(Area_cone_exact + 4*mypi*r^2))/100);

/* Mistake 2: included the cone's circular base (pi r^2) */
fullcone_mistake:float(round(100*(Area_cone_exact + mypi*r^2 + Hemisphere_exact))/100);

/* Mistake 3: found the VOLUME of the solid instead of the surface area:
   (1/3) pi r^2 h  +  (2/3) pi r^3 */
volume_mistake:float(round(100*( (1/3)*mypi*r^2*h + (2/3)*mypi*r^3 ))/100);
